'use strict';
const dropdowns=new Map();let openDropdown=null;
function closeDropdown(restore=false){if(!openDropdown)return;const c=openDropdown;openDropdown=null;c.menu.hidden=true;c.button.setAttribute('aria-expanded','false');c.button.removeAttribute('aria-activedescendant');if(restore)c.button.focus()}
function mountDropdown(select){if(dropdowns.has(select))return;const wrap=document.createElement('span');wrap.className='picker';select.before(wrap);wrap.append(select);select.classList.add('picker-native');select.tabIndex=-1;select.setAttribute('aria-hidden','true');const button=document.createElement('button');button.type='button';button.className='picker-trigger';button.id=select.id+'-trigger';button.setAttribute('role','combobox');button.setAttribute('aria-expanded','false');button.setAttribute('aria-haspopup','listbox');button.setAttribute('aria-label',select.getAttribute('aria-label')||({theme:'Appearance',refresh:'Refresh interval'})[select.id]||'Choose an option');wrap.append(button);
 const menu=document.createElement('div');menu.className='picker-menu';menu.id=select.id+'-menu';menu.setAttribute('role','listbox');menu.setAttribute('aria-label',button.getAttribute('aria-label'));menu.hidden=true;(select.closest('dialog')||document.body).append(menu);button.setAttribute('aria-controls',menu.id);const c={select,button,menu,index:0,signature:''};dropdowns.set(select,c);
 c.sync=()=>{const option=select.selectedOptions[0];button.innerHTML=`<span>${esc(option?.textContent||'Select')}</span><svg viewBox="0 0 16 16" aria-hidden="true"><path d="m4 6 4 4 4-4"/></svg>`;button.disabled=select.disabled;if(openDropdown===c)renderOptions(c)};
 button.onclick=()=>{if(openDropdown===c){closeDropdown();return}openMenu(c)};button.onkeydown=e=>{if(e.key==='Escape'){closeDropdown(true);e.preventDefault();return}if(e.key==='Tab'){closeDropdown();return}if(['ArrowDown','ArrowUp','Home','End','Enter',' '].includes(e.key)){e.preventDefault();if(!openDropdown||openDropdown!==c){openMenu(c);if(e.key==='Enter'||e.key===' ')return}const opts=[...select.options];if(e.key==='Enter'||e.key===' '){choose(c,c.index);return}let n=c.index;if(e.key==='Home')n=-1;if(e.key==='End')n=opts.length;const direction=e.key==='ArrowUp'||e.key==='End'?-1:1;for(let i=0;i<opts.length;i++){n=(n+direction+opts.length)%opts.length;if(!opts[n].disabled)break}c.index=n;highlight(c)}else if(e.key.length===1&&!e.ctrlKey&&!e.metaKey){if(openDropdown!==c)openMenu(c);const opts=[...select.options],found=opts.findIndex((o,i)=>i>c.index&&!o.disabled&&o.text.toLowerCase().startsWith(e.key.toLowerCase()));const n=found<0?opts.findIndex(o=>!o.disabled&&o.text.toLowerCase().startsWith(e.key.toLowerCase())):found;if(n>=0){c.index=n;highlight(c)}}};select.addEventListener('change',c.sync);new MutationObserver(c.sync).observe(select,{childList:true,subtree:true,attributes:true,attributeFilter:['disabled','label','selected']});c.sync()}
function renderOptions(c){c.menu.innerHTML=[...c.select.options].map((o,i)=>`<button type="button" role="option" id="${c.select.id}-option-${i}" aria-selected="${o.selected}" ${o.disabled?'disabled':''} data-index="${i}"><span>${esc(o.text)}</span><span class="picker-check" aria-hidden="true">${o.selected?'✓':''}</span></button>`).join('');c.menu.querySelectorAll('[data-index]').forEach(b=>{b.onpointerdown=e=>e.preventDefault();b.onclick=()=>choose(c,Number(b.dataset.index));b.onpointermove=()=>{if(!b.disabled){c.index=Number(b.dataset.index);highlight(c,false)}}});highlight(c,false)}
function positionMenu(c){const r=c.button.getBoundingClientRect(),vw=innerWidth,vh=innerHeight;const width=Math.min(Math.max(r.width,205),vw-24);c.menu.style.width=width+'px';c.menu.style.left=Math.max(12,Math.min(r.left,vw-width-12))+'px';const maxHeight=Math.min(340,vh-32);c.menu.style.maxHeight=maxHeight+'px';const height=Math.min(c.menu.scrollHeight,maxHeight);c.menu.style.top=(r.bottom+height+12>vh?Math.max(12,r.top-height-6):r.bottom+6)+'px'}
function openMenu(c){closeDropdown();openDropdown=c;c.index=Math.max(0,c.select.selectedIndex);renderOptions(c);c.menu.hidden=false;c.button.setAttribute('aria-expanded','true');positionMenu(c);highlight(c)}
function highlight(c,scroll=true){const opts=[...c.menu.querySelectorAll('[role=option]')];opts.forEach((o,i)=>o.classList.toggle('picker-highlight',i===c.index));const active=opts[c.index];if(active){c.button.setAttribute('aria-activedescendant',active.id);if(scroll)active.scrollIntoView({block:'nearest'})}}
function choose(c,index){const opt=c.select.options[index];if(!opt||opt.disabled)return;c.select.value=opt.value;c.select.dispatchEvent(new Event('change',{bubbles:true}));c.sync();closeDropdown(true)}
function syncDropdowns(){document.querySelectorAll('select').forEach(s=>{mountDropdown(s);const c=dropdowns.get(s);const signature=s.value+'|'+s.disabled+'|'+[...s.options].map(o=>o.text+o.disabled).join('|');if(signature!==c.signature){c.signature=signature;c.sync()}})}
document.addEventListener('pointerdown',e=>{if(openDropdown&&!openDropdown.menu.contains(e.target)&&!openDropdown.button.contains(e.target))closeDropdown()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&openDropdown){e.preventDefault();e.stopPropagation();closeDropdown(true)}},true);window.addEventListener('resize',()=>closeDropdown());window.addEventListener('scroll',e=>{if(openDropdown&&!openDropdown.menu.contains(e.target))closeDropdown()},true);

const refinedRender=render;render=function(){refinedRender();syncDropdowns()};const refinedOpenUsage=openUsage;openUsage=function(...args){closeDropdown();refinedOpenUsage(...args);syncDropdowns()};
syncDropdowns();
